import { NextRequest, NextResponse } from "next/server";
import { supabaseAdmin } from "@/lib/supabase/server";
import { widgetConfigSchema } from "@atelier/shared";

export async function GET(request: NextRequest) {
  try {
    if (!supabaseAdmin) {
      return NextResponse.json(
        { error: "Database not configured" },
        { status: 500 }
      );
    }

    const searchParams = request.nextUrl.searchParams;
    const shopId = searchParams.get("shopId");
    const productId = searchParams.get("productId");
    const sku = searchParams.get("sku");
    const handle = searchParams.get("handle");
    const url = searchParams.get("url");

    if (!shopId) {
      return NextResponse.json(
        { error: "shopId is required" },
        { status: 400 }
      );
    }

    // Find product by various identifiers
    let productQuery = supabaseAdmin
      .from("products")
      .select("id, status")
      .eq("shop_id", shopId)
      .eq("status", "published");

    if (productId) {
      productQuery = productQuery.eq("id", productId);
    } else if (sku) {
      productQuery = productQuery.eq("sku", sku);
    } else if (handle) {
      productQuery = productQuery.eq("handle", handle);
    } else if (url) {
      productQuery = productQuery.eq("url", url);
    } else {
      return NextResponse.json(
        {
          enabled: false,
        },
        { status: 200 }
      );
    }

    const { data: products, error: productError } = await productQuery.limit(1);

    if (productError) {
      console.error("Error fetching product:", productError);
      return NextResponse.json(
        { error: "Failed to fetch product" },
        { status: 500 }
      );
    }

    if (!products || products.length === 0) {
      return NextResponse.json(
        {
          enabled: false,
        },
        { status: 200 }
      );
    }

    const product = products[0];

    // Fetch assets for this product
    const { data: assets, error: assetsError } = await supabaseAdmin
      .from("assets")
      .select("size, glb_url, version")
      .eq("product_id", product.id)
      .order("version", { ascending: false });

    if (assetsError) {
      console.error("Error fetching assets:", assetsError);
      return NextResponse.json(
        { error: "Failed to fetch assets" },
        { status: 500 }
      );
    }

    // Group assets by size (get latest version for each size)
    const sizeMap = new Map<string, { glbUrl: string }>();
    const versions = new Map<string, number>();

    assets?.forEach((asset) => {
      const currentVersion = versions.get(asset.size) || 0;
      if (asset.version > currentVersion) {
        sizeMap.set(asset.size, { glbUrl: asset.glb_url });
        versions.set(asset.size, asset.version);
      }
    });

    const config = {
      enabled: true,
      asset:
        sizeMap.size > 0
          ? {
              defaultSize: "M" as const,
              sizes: Object.fromEntries(sizeMap),
            }
          : undefined,
    };

    // Validate response with schema
    const validated = widgetConfigSchema.parse(config);

    return NextResponse.json(validated);
  } catch (error) {
    console.error("Error in widget-config:", error);
    return NextResponse.json(
      { error: "Internal server error" },
      { status: 500 }
    );
  }
}
